(() => {
  const DAY_MS = 864e5;
  const ALLOWED = new Set(["checkDate", "expiryDate"]);
  function toUtcDay(value, name) {
    if (typeof value !== "string") {
      throw new Error("invalid date: " + name);
    }
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!m) {
      throw new Error("invalid date: " + name);
    }
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    const t = Date.UTC(y, mo - 1, d);
    const dt = new Date(t);
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) {
      throw new Error("invalid date: " + name);
    }
    return t;
  }
  function checkIdentityDocument(input) {
    if (input === null || typeof input !== "object") {
      throw new Error("invalid input");
    }
    for (const key of Object.keys(input)) {
      if (!ALLOWED.has(key)) {
        throw new Error("unknown field: " + key);
      }
    }
    const check = toUtcDay(input.checkDate, "checkDate");
    const expiry = toUtcDay(input.expiryDate, "expiryDate");
    const daysUntilExpiry = Math.round((expiry - check) / DAY_MS);
    const accepted = daysUntilExpiry >= 30;
    return { accepted, daysUntilExpiry };
  }
  return { checkIdentityDocument };
})()

