build.unitScript:
test("AC-1: checked 2026-06-01, expiring 2026-07-01 gives 30 days and is accepted", () => {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("AC-2: checked 2026-06-01, expiring 2026-06-30 gives 29 days and is rejected", () => {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }), { accepted: false, daysUntilExpiry: 29 });
});
test("document expiring on the check date gives 0 days and is rejected", () => {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-01" }), { accepted: false, daysUntilExpiry: 0 });
});
test("document that already expired gives a negative day count and is rejected", () => {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-05-31" }), { accepted: false, daysUntilExpiry: -1 });
});
test("counts calendar days across a leap-year February: 2028-02-01 to 2028-03-02 is 30 days and accepted", () => {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2028-02-01", expiryDate: "2028-03-02" }), { accepted: true, daysUntilExpiry: 30 });
});
test("an extra input field is refused with an unknown field error naming it", () => {
  assert.throws(() => code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01", country: "GB" }), /unknown field: country/);
});

