test("accepts a document expiring exactly 30 days after the check and returns both fields", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("rejects a document expiring 29 days after the check", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});
test("accepts a document expiring 31 days after the check", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-02" }),
    { accepted: true, daysUntilExpiry: 31 }
  );
});
test("rejects a document expiring one day after the check", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-02" }),
    { accepted: false, daysUntilExpiry: 1 }
  );
});
test("counts exactly 30 days from March 2 to April 1 across a 31 day March", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-03-02", expiryDate: "2026-04-01" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("counts exactly 30 days from the last day of April to May 30", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-04-30", expiryDate: "2026-05-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("counts 30 days from January 1 to the last day of January", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-01-01", expiryDate: "2026-01-31" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("counts exactly 30 days from December 2 to January 1 across the year boundary", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-12-02", expiryDate: "2027-01-01" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("rejects a document 29 days from December 3 to January 1", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-12-03", expiryDate: "2027-01-01" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});
test("counts exactly 30 days from leap day to March 30", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-30" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("rejects 29 days from February 1 to March 2 in a non-leap year", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-02-01", expiryDate: "2026-03-02" }),
    { accepted: false, daysUntilExpiry: 29 }
  );
});
test("counts exactly 30 days when the expiry date is leap day", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2024-01-30", expiryDate: "2024-02-29" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("counts exactly 30 days when leap day falls in the middle of the span", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2024-02-28", expiryDate: "2024-03-29" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("counts exactly 30 days from the last day of December to January 30", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-12-31", expiryDate: "2027-01-30" }),
