  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-01-31", expiryDate: "2026-03-02" }),
    { accepted: true, daysUntilExpiry: 30 }
  );
});
test("accepts a document with 59 days from January 1 to March 1 through a non-leap February", function() {
  assert.deepEqual(
    code.checkIdentityDocument({ checkDate: "2026-01-01", expiryDate: "2026-03-01" }),
    { accepted: true, daysUntilExpiry: 59 }
  );
});

